function validate([s, a, b]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 100) return 's needs 2 to 100 characters.';
  if (s.length % 2 !== 0) return 's must have an even length.';
  if (!/^[0-9]+$/.test(s)) return 's may contain only digits.';
  if (!Number.isInteger(a) || a < 1 || a > 9) return 'a is between 1 and 9.';
  if (!Number.isInteger(b) || b < 1 || b > s.length - 1) return 'b is between 1 and s.length - 1.';
  return null;
}

