function findLexSmallestString(s, a, b) {
  // Enumerate every rotation offset and every number of adds on odd and (when b is odd) even positions.
  const n = s.length;
  let best = s;
  const evenChoices = b % 2 === 1 ? 10 : 1;
  for (let k = 0; k < n; k++) {
    const shift = (k * b) % n;
    const rotated = s.slice(n - shift) + s.slice(0, n - shift);
    for (let x = 0; x < 10; x++) {
      for (let y = 0; y < evenChoices; y++) {
        let candidate = '';
        for (let i = 0; i < n; i++) {
          const add = i % 2 === 1 ? x * a : y * a;
          candidate += (Number(rotated[i]) + add) % 10;
        }
        if (candidate < best) best = candidate;
      }
    }
  }
  return best;
}

