function generate(rand, size) {
  const n = size === 'large' ? 100 - 2 * Math.floor(rand() * 5) : 2 * (1 + Math.floor(rand() * 4));
  const top = rand() < 0.3 ? 3 : 10;
  let s = '';
  for (let i = 0; i < n; i++) s += Math.floor(rand() * top);
  const a = 1 + Math.floor(rand() * 9);
  const b = 1 + Math.floor(rand() * (n - 1));
  return [s, a, b];
}
